import React, { useState } from 'react';
import CustomerList from './components/CustomerList';
import CustomerRegistrationForm from './components/CustomerRegistrationForm';
import CustomerDetails from './components/CustomerDetails';
import AboutPage from './components/AboutPage';
import Dashboard from './components/Dashboard';
import AgentList from './components/AgentList';
import HomePage from './components/HomePage';
import TaskPage from './components/TaskPage';
import LoginPage from './components/LoginPage';
import './App.css';
import { SignedIn, SignedOut, UserButton } from '@clerk/clerk-react';
import { FaMoon, FaSun, FaInfoCircle } from "react-icons/fa";

function App() {
  const [selectedCustomerId, setSelectedCustomerId] = useState(null);
  const [refreshList, setRefreshList] = useState(false);
  const [currentPage, setCurrentPage] = useState('home');
  const [darkMode, setDarkMode] = useState(false);

  const toggleDarkMode = () => {
    console.log("Dark mode toggled:", !darkMode);
    setDarkMode(prev => !prev);
  };

  const goToPage = (page) => {
    setCurrentPage(page);
    setSelectedCustomerId(null); // Reset selection when switching tabs
    if (page === 'customers') {
      setRefreshList(prev => !prev); // Force reload list when entering customers tab
    }
  };

  return (
    <div className={`app-container${darkMode ? " dark-mode" : ""}`}>
      <SignedIn>
        <header className="app-header">
          {/* Left Group: CRM title + login + dark mode */}
          <div className="branding">
            <h1 className="glitter-title">-CRM System-</h1>
            <span className="login-btn">
              <UserButton />
            </span>
            <span
              className="darkmode-toggle"
              onClick={toggleDarkMode}
              title="Toggle Dark Mode"
              role="button"
              tabIndex={0}
            >
              {darkMode ? <FaSun size={22} /> : <FaMoon size={22} />}
            </span>
          </div>

          {/* Navigation */}
          <nav className="nav-tabs">
            <button
              className={currentPage === 'home' ? 'nav-tab active' : 'nav-tab'}
              onClick={() => goToPage('home')}
            >Home</button>
            <button
              className={currentPage === 'dashboard' ? 'nav-tab active' : 'nav-tab'}
              onClick={() => goToPage('dashboard')}
            >Dashboard</button>
            <button
              className={currentPage === 'agents' ? 'nav-tab active' : 'nav-tab'}
              onClick={() => goToPage('agents')}
            >Agents</button>
            <button
              className={currentPage === 'tasks' ? 'nav-tab active' : 'nav-tab'}
              onClick={() => goToPage('tasks')}
            >Tasks</button>
            <button
              className={currentPage === 'customers' ? 'nav-tab active' : 'nav-tab'}
              onClick={() => goToPage('customers')}
            >Customers</button>
            <button
              className={currentPage === 'about' ? 'nav-tab active' : 'nav-tab'}
              onClick={() => goToPage('about')}
            >
              <FaInfoCircle style={{ marginRight: "6px", verticalAlign: "middle" }} /> About
            </button>
          </nav>
        </header>

        {/* Page Content */}
        <main>
          {currentPage === 'home' && <HomePage />}
          {currentPage === 'dashboard' && <Dashboard />}
          {currentPage === 'agents' && <AgentList />}
          {currentPage === 'tasks' && <TaskPage />}

          {currentPage === 'customers' && (
            !selectedCustomerId ? (
              <div className="crm-side-by-side">
                <div className="crm-left">
                  <CustomerRegistrationForm onCreate={() => setRefreshList(prev => !prev)} />
                </div>
                <div className="crm-right">
                  <CustomerList key={refreshList} onSelect={id => setSelectedCustomerId(id)} />
                </div>
              </div>
            ) : (
              <div className="content">
                <div className="form-container" style={{ width: '100%' }}>
                  <CustomerDetails
                    customerId={selectedCustomerId}
                    onBack={() => setSelectedCustomerId(null)}
                  />
                </div>
              </div>
            )
          )}

          {currentPage === 'about' && <AboutPage />}
        </main>
      </SignedIn>

      {/* Signed Out View */}
      <SignedOut>
        <LoginPage />
      </SignedOut>
    </div>
  );
}

export default App;
